using Kerf.Engine.Foundation;
using System.Text;
using static Occt.Interface_ParamType;

namespace Occt;

/// <summary>
/// The STEP scanner (OCCT's <c>step::scanner</c>, generated by flex from <c>step.lex</c>), written by hand: it
/// returns the tokens flex's tables return, with the same texts and the same calls into
/// <see cref="StepFile_ReadData"/> (CreateNewText, SetTypeArg, PrepareNewArg), and counts lines as OCCT does.
/// </summary>
/// <remarks>
/// <para>
/// Flex picks, at each point, the rule matching the longest text, the first in step.lex on a tie (a rule's trailing
/// context counts in its length), and the scanner does the same, rule by rule: the rules' numbers below are flex's
/// (lex.step.cxx's actions). Like OCCT's (<c>%option case-insensitive</c>), it ignores the letters' case.
/// </para>
/// <para>
/// OCCT's scanner keeps a token (with what <c>yymore</c> collected: a quoted string's pieces) in a buffer of 16,384
/// bytes that it can't enlarge (its variable trailing context makes flex's REJECT machinery hold one state per
/// byte), so it throws (<c>YY_FATAL_ERROR</c>: "input buffer overflow, can't enlarge buffer because scanner uses
/// REJECT") when it has to look at a token's 16,384th byte. This scanner throws the same
/// <see cref="FailureException"/> at the same byte (<see cref="MaxToken"/>).
/// </para>
/// <para>
/// Reentrant: each read has its own scanner, parser and data. It reads the stream in blocks.
/// </para>
/// </remarks>
public sealed class StepFile_Scanner
{
    // The start conditions (%x Com End Text)
    private const int INITIAL = 0;
    private const int Com = 1;
    private const int End = 2;
    private const int Text = 3;

    /// <summary>
    /// The index, from a token's start, of the first byte OCCT's scanner can't look at (YY_BUF_SIZE - 1: flex
    /// refills the buffer with at most yy_buf_size - number_to_move - 1 bytes and fails at 0).
    /// </summary>
    internal const int MaxToken = 16383;

    private const string theOverflow = "input buffer overflow, can't enlarge buffer because scanner uses REJECT";

    internal readonly StepFile_ReadData myDataModel;
    private readonly Stream myStream;
    private readonly StepFile_ReadLimits myLimits;
    private byte[] myBuf = new byte[1 << 18];
    private int myLen; // bytes held in myBuf
    private bool myEof; // the stream is at its end (myLen is the input's end)
    private long myRead; // bytes read from the stream
    private int myPos; // where the next token starts (yy_c_buf_p)
    private int myTextStart; // in Text, where the quoted string started (yymore's text)
    private int myCap; // the current token's start + MaxToken
    private int myStart = INITIAL; // yy_start
    private int yylineno = 1;

    /// <summary>A scanner reading <paramref name="theStream"/> for <paramref name="theDataModel"/>.</summary>
    public StepFile_Scanner(StepFile_ReadData theDataModel, Stream theStream, StepFile_ReadLimits? theLimits = null)
    {
        myDataModel = theDataModel;
        myStream = theStream;
        myLimits = theLimits ?? StepFile_ReadLimits.Default;
    }

    /// <summary>The line counter (FlexLexer's lineno(): starts at 1, counts the newlines read).</summary>
    public int lineno() => yylineno;

    /// <summary>The limits for hostile input.</summary>
    internal StepFile_ReadLimits Limits => myLimits;

    /// <summary>Bytes read from the stream so far.</summary>
    internal long BytesRead => myRead;

    /// <summary>The input's length if the stream knows it, else -1.</summary>
    internal long InputLength
    {
        get
        {
            try
            {
                return myStream.CanSeek ? myStream.Length : -1;
            }
            catch (NotSupportedException)
            {
                return -1;
            }
        }
    }

    /// <summary>Raised when the input passes <see cref="StepFile_ReadLimits.MaxFileSize"/>.</summary>
    internal sealed class FileTooLarge : Exception { }

    private void CreateNewText(int theFrom, int theTo)
    {
        myDataModel.CreateNewText(Encoding.Latin1.GetString(myBuf, theFrom, theTo - theFrom), theTo - theFrom);
    }

    private void SetTypeArg(Interface_ParamType theType) => myDataModel.SetTypeArg(theType);

    /// <summary>
    /// The next token (<see cref="StepFile_Parser.token"/>; 0 at the end of the input), with the scanner's actions
    /// done (OCCT's <c>lex</c>, YY_DECL).
    /// </summary>
    internal int lex()
    {
        for (;;)
        {
            int p = myPos;
            int aTokStart = myStart == Text ? myTextStart : p;
            if (!myEof && myLen - aTokStart <= MaxToken)
            {
                Refill(aTokStart);
                p = myPos;
                aTokStart = myStart == Text ? myTextStart : p;
            }

            myCap = aTokStart + MaxToken;
            int c = Peek(p);
            switch (myStart)
            {
                case Com:
                    if (c < 0)
                    {
                        return 0;
                    }

                    if (c == '\n')
                    {
                        // 12: <*>[\n]
                        yylineno++;
                        myPos = p + 1;
                    }
                    else if (c == '*')
                    {
                        int i = p + 1;
                        while (Peek(i) == '*')
                        {
                            i++;
                        }

                        if (Peek(i) == '/')
                        {
                            // 4: <Com>[*]+[/], end of comment
                            myPos = i + 1;
                            myStart = INITIAL;
                        }
                        else
                        {
                            // 3: <Com>[*]+[^*/\n]*
                            for (c = Peek(i); c >= 0 && c != '*' && c != '/' && c != '\n'; c = Peek(++i)) { }
                            myPos = i;
                        }
                    }
                    else
                    {
                        // 2: <Com>[^*\n]*
                        int i = p + 1;
                        for (c = Peek(i); c >= 0 && c != '*' && c != '\n'; c = Peek(++i)) { }
                        myPos = i;
                    }

                    continue;

                case End:
                    if (c < 0)
                    {
                        return 0;
                    }

                    if (c == '\n')
                    {
                        yylineno++;
                        myPos = p + 1;
                    }
                    else
                    {
                        // 43: <End>[^\n], one byte at a time in flex: the run at once here
                        int i = p + 1;
                        while (i < myCap && i < myLen && myBuf[i] != '\n')
                        {
                            i++;
                        }

                        myPos = i;
                    }

                    continue;

                case Text:
                    if (c < 0)
                    {
                        // The end of the input in a string: flex's yyterminate drops what yymore collected
                        return 0;
                    }

                    if (c == '\n')
                    {
                        // 6: <Text>[\n], yymore
                        yylineno++;
                        myPos = p + 1;
                    }
                    else if (c == '\'')
                    {
                        // 9: <Text>[']/[" "\n\r]*[\)\,], the end of the string. OCCT: the class [" "\n\r] holds
                        // the double quote with the blank, CR and LF, and not the tab, so 'a' \t, goes on
                        int j = p + 1;
                        int d;
                        for (d = Peek(j); d == ' ' || d == '"' || d == '\n' || d == '\r'; d = Peek(++j)) { }
                        myPos = p + 1;
                        if (d == ')' || d == ',')
                        {
                            myStart = INITIAL;
                            CreateNewText(myTextStart, p + 1);
                            SetTypeArg(Interface_ParamText);
                            return StepFile_Parser.token.QUID;
                        }

                        // 7: <Text>['], yymore
                    }
                    else
                    {
                        // 8: <Text>[^\n']+, yymore
                        int i = p + 1;
                        for (c = Peek(i); c >= 0 && c != '\n' && c != '\''; c = Peek(++i)) { }
                        myPos = i;
                    }

                    continue;
            }

            // INITIAL
            switch (c)
            {
                case < 0:
                    return 0;
                case '\n':
                    // 12: <*>[\n]
                    yylineno++;
                    myPos = p + 1;
                    continue;
                case ' ':
                case '\t':
                case '\r':
                    // 10, 11, 13 (abv 30.06.00: for reading DOS files)
                    myPos = p + 1;
                    continue;
                case 0:
                {
                    // 14: [\0]+ (fix from C21. for test load e3i file with line 15 with null symbols)
                    int i = p + 1;
                    while (Peek(i) == 0)
                    {
                        i++;
                    }

                    myPos = i;
                    continue;
                }
                case '/':
                    if (Peek(p + 1) == '*')
                    {
                        // 1: "/*", start of comment
                        myStart = Com;
                        myPos = p + 2;
                        continue;
                    }

                    // 37: [/]
                    myPos = p + 1;
                    return '/';
                case '\'':
                    // 5: ['], start of quoted text string, kept as part of the text (yymore)
                    myStart = Text;
                    myTextStart = p;
                    myPos = p + 1;
                    continue;
                case '(':
                    myPos = p + 1;
                    return '(';
                case ')':
                    myPos = p + 1;
                    return ')';
                case ',':
                    myPos = p + 1;
                    myDataModel.PrepareNewArg();
                    return ',';
                case '$':
                    myPos = p + 1;
                    CreateNewText(p, p + 1);
                    SetTypeArg(Interface_ParamVoid);
                    return StepFile_Parser.token.QUID;
                case '=':
                    myPos = p + 1;
                    return '=';
                case ';':
                    myPos = p + 1;
                    return ';';
                case '#':
                {
                    int i = p + 1;
                    while (IsDigit(Peek(i)))
                    {
                        i++;
                    }

                    if (i == p + 1)
                    {
                        return Misc(p);
                    }

                    // 15: #[0-9]+/=, 16: #[0-9]+/[ \t]*= (the entity's label), 17: #[0-9]+ (a reference)
                    int j = i;
                    int d;
                    for (d = Peek(j); d == ' ' || d == '\t'; d = Peek(++j)) { }
                    myPos = i;
                    CreateNewText(p, i);
                    return d == '=' ? StepFile_Parser.token.ENTITY : StepFile_Parser.token.IDENT;
                }
                case '"':
                {
                    // 21: ["][0-9A-F]+["]
                    int i = p + 1;
                    while (IsHex(Peek(i)))
                    {
                        i++;
                    }

                    if (i == p + 1 || Peek(i) != '"')
                    {
                        return Misc(p);
                    }

                    myPos = i + 1;
                    CreateNewText(p, i + 1);
                    SetTypeArg(Interface_ParamHexa);
                    return StepFile_Parser.token.QUID;
                }
                case '&':
                {
                    // 38: &(?i:SCOPE)
                    if (MatchWord(p + 1, "SCOPE") == p + 6)
                    {
                        myPos = p + 6;
                        return StepFile_Parser.token.SCOPE;
                    }

                    return Misc(p);
                }
                case '!':
                {
                    // 41: ![a-zA-Z0-9_]+
                    int i = p + 1;
                    while (IsWord(Peek(i)))
                    {
                        i++;
                    }

                    if (i == p + 1)
                    {
                        return Misc(p);
                    }

                    myPos = i;
                    CreateNewText(p, i);
                    return StepFile_Parser.token.TYPE;
                }
            }

            if (c == '-' || c == '+' || c == '.' || IsWord(c))
            {
                return Word(p, c);
            }

            return Misc(p);
        }
    }

    /// <summary>42: [^)], any other byte: a parameter of unknown kind.</summary>
    private int Misc(int p)
    {
        myPos = p + 1;
        CreateNewText(p, p + 1);
        SetTypeArg(Interface_ParamMisc);
        return StepFile_Parser.token.QUID;
    }

    /// <summary>
    /// The rules starting with a sign, a dot, a digit, a letter or an underscore: the numbers (18 to 20), the
    /// enumerations (22), the keywords (29 to 36, 39) and the names (40), the longest match winning, then the first.
    /// </summary>
    private int Word(int p, int c)
    {
        // 42 ([^)], one byte) unless a rule matches (a tie goes to the other rule, which comes first)
        int aBest = 42;
        int aLen = 0;

        void Take(int theRule, int theLen)
        {
            if (theLen > aLen)
            {
                aBest = theRule;
                aLen = theLen;
            }
        }

        bool isDigit = IsDigit(c);
        // 18: [-+0-9][0-9]*
        if (isDigit || c == '-' || c == '+')
        {
            int i = p + 1;
            while (IsDigit(Peek(i)))
            {
                i++;
            }

            Take(18, i - p);
        }

        // 19: [-+\.0-9][\.0-9]+, 20: [-+\.0-9][\.0-9]+E[-+0-9][0-9]*
        if (isDigit || c == '-' || c == '+' || c == '.')
        {
            int j = p + 1;
            int d;
            for (d = Peek(j); IsDigit(d) || d == '.'; d = Peek(++j)) { }
            if (j > p + 1)
            {
                Take(19, j - p);
                if ((d == 'E' || d == 'e') && (IsDigit(d = Peek(j + 1)) || d == '-' || d == '+'))
                {
                    int k = j + 2;
                    while (IsDigit(Peek(k)))
                    {
                        k++;
                    }

                    Take(20, k - p);
                }
            }
        }

        // 22: [.]*[A-Z0-9_]+[.]
        if (c == '.' || IsWord(c))
        {
            int a = p;
            while (Peek(a) == '.')
            {
                a++;
            }

            int b = a;
            while (IsWord(Peek(b)))
            {
                b++;
            }

            if (b > a && Peek(b) == '.')
            {
                Take(22, b + 1 - p);
            }
        }

        if (IsLetter(c))
        {
            // The keywords
            int k;
            switch (c | 0x20)
            {
                case 's':
                    // 29: (?i:STEP);
                    if (MatchWord(p, "STEP;") == p + 5)
                    {
                        Take(29, 5);
                    }

                    break;
                case 'h':
                    // 30: (?i:HEADER);
                    if (MatchWord(p, "HEADER;") == p + 7)
                    {
                        Take(30, 7);
                    }

                    break;
                case 'd':
                    // 32: (?i:DATA);
                    if (MatchWord(p, "DATA;") == p + 5)
                    {
                        Take(32, 5);
                    }

                    break;
                case 'e':
                    k = MatchWord(p, "END");
                    if (k == p + 3)
                    {
                        int d = Peek(k);
                        if ((d | 0x20) == 's')
                        {
                            // 31: (?i:ENDSEC); 33: (?i:ENDSTEP); 34: (?i:ENDSTEP);.* 39: (?i:ENDSCOPE)
                            if (MatchWord(p, "ENDSEC;") == p + 7)
                            {
                                Take(31, 7);
                            }
                            else if (MatchWord(p, "ENDSCOPE") == p + 8)
                            {
                                Take(39, 8);
                            }
                            else if (MatchWord(p, "ENDSTEP;") == p + 8)
                            {
                                Take(33, 8);
                                int i = p + 8;
                                for (d = Peek(i); d >= 0 && d != '\n'; d = Peek(++i)) { }
                                Take(34, i - p);
                            }
                        }
                        else if (d == '-')
                        {
                            // 35: (?i:END-ISO)[0-9\-]*;
                            k = MatchWord(p, "END-ISO");
                            if (k == p + 7)
                            {
                                while (IsDigit(d = Peek(k)) || d == '-')
                                {
                                    k++;
                                }

                                if (d == ';')
                                {
                                    Take(35, k + 1 - p);
                                }
                            }
                        }
                    }

                    break;
                case 'i':
                    // 36: (?i:ISO)[0-9\-]*;
                    k = MatchWord(p, "ISO");
                    if (k == p + 3)
                    {
                        int d;
                        while (IsDigit(d = Peek(k)) || d == '-')
                        {
                            k++;
                        }

                        if (d == ';')
                        {
                            Take(36, k + 1 - p);
                        }
                    }

                    break;
            }
        }

        // 40: [a-zA-Z0-9_]+
        if (IsWord(c))
        {
            int i = p + 1;
            while (IsWord(Peek(i)))
            {
                i++;
            }

            Take(40, i - p);
        }

        myPos = p + aLen;
        switch (aBest)
        {
            case 18:
                CreateNewText(p, p + aLen);
                SetTypeArg(Interface_ParamInteger);
                return StepFile_Parser.token.QUID;
            case 19:
            case 20:
                CreateNewText(p, p + aLen);
                SetTypeArg(Interface_ParamReal);
                return StepFile_Parser.token.QUID;
            case 22:
                CreateNewText(p, p + aLen);
                SetTypeArg(Interface_ParamEnum);
                return StepFile_Parser.token.QUID;
            case 29:
            case 36:
                return StepFile_Parser.token.STEP;
            case 30:
                return StepFile_Parser.token.HEADER;
            case 31:
                return StepFile_Parser.token.ENDSEC;
            case 32:
                return StepFile_Parser.token.DATA;
            case 33:
            case 34:
                return StepFile_Parser.token.ENDSTEP;
            case 35:
                // at the end of the STEP data, the dedicated start condition End skips everything that follows
                myStart = End;
                return StepFile_Parser.token.ENDSTEP;
            case 39:
                return StepFile_Parser.token.ENDSCOPE;
            case 40:
                CreateNewText(p, p + aLen);
                return StepFile_Parser.token.TYPE;
            default:
                return Misc(p);
        }
    }

    /// <summary>
    /// The byte at <paramref name="i"/>, -1 at the end of the input; looking at a token's 16,384th byte throws, as
    /// OCCT's scanner does.
    /// </summary>
    private int Peek(int i)
    {
        if (i >= myCap)
        {
            // OCCT: flex can't grow its buffer (see the class's remarks)
            throw new FailureException(theOverflow);
        }

        return i < myLen ? myBuf[i] : -1;
    }

    /// <summary>Where the case-insensitive match of <paramref name="theWord"/> at <paramref name="p"/> stops.</summary>
    private int MatchWord(int p, string theWord)
    {
        for (int i = 0; i < theWord.Length; i++)
        {
            int c = Peek(p + i);
            char w = theWord[i];
            if (c != w && !(w is >= 'A' and <= 'Z' && c == (w | 0x20)))
            {
                return p + i;
            }
        }

        return p + theWord.Length;
    }

    private static bool IsDigit(int c) => (uint)(c - '0') <= 9;

    private static bool IsLetter(int c) => (uint)((c | 0x20) - 'a') <= 'z' - 'a';

    private static bool IsWord(int c) => IsDigit(c) || IsLetter(c) || c == '_';

    private static bool IsHex(int c) => IsDigit(c) || (uint)((c | 0x20) - 'a') <= 'f' - 'a';

    /// <summary>
    /// Moves the current token to the buffer's start and reads, so that the buffer holds the token's
    /// <see cref="MaxToken"/> + 1 bytes, or the input's end.
    /// </summary>
    private void Refill(int theTokStart)
    {
        if (theTokStart > 0)
        {
            Buffer.BlockCopy(myBuf, theTokStart, myBuf, 0, myLen - theTokStart);
            myLen -= theTokStart;
            myPos -= theTokStart;
            myTextStart -= theTokStart;
        }

        while (myLen < myBuf.Length)
        {
            int aRead = myStream.Read(myBuf, myLen, myBuf.Length - myLen);
            if (aRead <= 0)
            {
                myEof = true;
                break;
            }

            myLen += aRead;
            myRead += aRead;
            if (myRead > myLimits.MaxFileSize)
            {
                throw new FileTooLarge();
            }
        }
    }
}
